//! Reader for `fixtures/text-glyph-contours/oracle.txt` (G38b / L06-B).
//!
//! The fixture is generated by `tools/gen.js` from the REAL baseline
//! `otPathToContours` / `contourBBox` / `contoursToMergedPaths` /
//! `_mergeHoleIntoExterior` at fbe4b8a3 (Node vm) and from the vendored
//! Paper.js `Segment#_transformCoordinates` for the shear. Row grammar:
//!
//! * `TAN12 v`: `Math.tan(12 * Math.PI / 180)`.
//! * `CASE name italic` (`-` or `skew,baselineY`), then `CMD ...` rows
//!   (`M x y`, `L x y`, `Q x1 y1 x y`, `C x1 y1 x2 y2 x y`, `Z`).
//! * Either `FAIL kind` (the baseline threw) or `CONT n`, `S ci x y hix hiy
//!   hox hoy`, `BOX ci minX minY maxX maxY`, `MERGE ext hole` (call order of the
//!   real `_mergeHoleIntoExterior`), `OUT n`, `P k nseg` + `G` rows, and for
//!   italic cases `PS k nseg` + `GS` rows (after the shear).
//! * `END`.
//!
//! Numbers are JS `String(n)`; `-0` prints as `0`, so every comparison is `==`.

use super::{ContourBox, GlyphSegment, OutlineCommand};

pub(crate) const ORACLE: &str = include_str!("fixtures/text-glyph-contours/oracle.txt");

#[derive(Debug)]
pub(crate) struct Case {
    pub(crate) name: String,
    pub(crate) italic: Option<(f64, f64)>,
    pub(crate) commands: Vec<OutlineCommand>,
    pub(crate) fails: bool,
    pub(crate) contours: Vec<Vec<GlyphSegment>>,
    pub(crate) boxes: Vec<ContourBox>,
    pub(crate) merges: Vec<(usize, usize)>,
    pub(crate) out_count: usize,
    pub(crate) merged: Vec<Vec<GlyphSegment>>,
    pub(crate) merged_counts: Vec<usize>,
    pub(crate) sheared: Vec<Vec<GlyphSegment>>,
    pub(crate) sheared_counts: Vec<usize>,
}

pub(crate) struct Oracle {
    pub(crate) tan12: f64,
    pub(crate) cases: Vec<Case>,
}

fn num(token: &str) -> f64 {
    token
        .parse::<f64>()
        .unwrap_or_else(|_| panic!("bad number {token:?}"))
}

fn nums(tokens: &[&str]) -> Vec<f64> {
    tokens.iter().map(|t| num(t)).collect()
}

fn index(token: &str) -> usize {
    token
        .parse::<usize>()
        .unwrap_or_else(|_| panic!("bad index {token:?}"))
}

fn segment(tokens: &[&str]) -> GlyphSegment {
    let v = nums(tokens);
    assert_eq!(v.len(), 6, "segment rows carry six numbers");
    GlyphSegment {
        point: [v[0], v[1]],
        handle_in: [v[2], v[3]],
        handle_out: [v[4], v[5]],
    }
}

fn command(tokens: &[&str]) -> OutlineCommand {
    let v = nums(&tokens[1..]);
    match tokens[0] {
        "M" => OutlineCommand::Move { x: v[0], y: v[1] },
        "L" => OutlineCommand::Line { x: v[0], y: v[1] },
        "Q" => OutlineCommand::Quad {
            x1: v[0],
            y1: v[1],
            x: v[2],
            y: v[3],
        },
        "C" => OutlineCommand::Cubic {
            x1: v[0],
            y1: v[1],
            x2: v[2],
            y2: v[3],
            x: v[4],
            y: v[5],
        },
        "Z" => OutlineCommand::Close,
        other => panic!("unknown command {other:?}"),
    }
}

fn new_case(tokens: &[&str]) -> Case {
    let italic = if tokens[2] == "-" {
        None
    } else {
        let (skew, base) = tokens[2].split_once(',').expect("italic skew,baseline");
        Some((num(skew), num(base)))
    };
    Case {
        name: tokens[1].to_string(),
        italic,
        commands: Vec::new(),
        fails: false,
        contours: Vec::new(),
        boxes: Vec::new(),
        merges: Vec::new(),
        out_count: 0,
        merged: Vec::new(),
        merged_counts: Vec::new(),
        sheared: Vec::new(),
        sheared_counts: Vec::new(),
    }
}

/// Appends a `G` / `GS` row to path `k` of `paths`, which `P` / `PS` created.
fn push_row(paths: &mut [Vec<GlyphSegment>], row: &[&str]) {
    paths
        .last_mut()
        .expect("segment row before its path header")
        .push(segment(row));
}

pub(crate) fn parse_oracle() -> Oracle {
    let mut tan12 = None;
    let mut cases: Vec<Case> = Vec::new();
    for line in ORACLE.lines() {
        if line.is_empty() || line.starts_with('#') {
            continue;
        }
        let tokens: Vec<&str> = line.split_whitespace().collect();
        if tokens[0] == "TAN12" {
            tan12 = Some(num(tokens[1]));
            continue;
        }
        if tokens[0] == "CASE" {
            cases.push(new_case(&tokens));
            continue;
        }
        let case = cases.last_mut().expect("row before the first CASE");
        match tokens[0] {
            "CMD" => case.commands.push(command(&tokens[1..])),
            "FAIL" => case.fails = true,
            "CONT" => {
                case.contours = vec![Vec::new(); index(tokens[1])];
            }
            "S" => case.contours[index(tokens[1])].push(segment(&tokens[2..])),
            "BOX" => {
                let v = nums(&tokens[2..]);
                assert_eq!(index(tokens[1]), case.boxes.len(), "BOX rows are in order");
                case.boxes.push(ContourBox {
                    min_x: v[0],
                    min_y: v[1],
                    max_x: v[2],
                    max_y: v[3],
                });
            }
            "MERGE" => case.merges.push((index(tokens[1]), index(tokens[2]))),
            "OUT" => case.out_count = index(tokens[1]),
            "END" => {}
            "P" => {
                case.merged.push(Vec::new());
                case.merged_counts.push(index(tokens[2]));
            }
            "PS" => {
                case.sheared.push(Vec::new());
                case.sheared_counts.push(index(tokens[2]));
            }
            "G" => push_row(&mut case.merged, &tokens[1..]),
            "GS" => push_row(&mut case.sheared, &tokens[1..]),
            other => panic!("unknown oracle row {other:?}"),
        }
    }
    Oracle {
        tan12: tan12.expect("TAN12 row"),
        cases,
    }
}

pub(crate) fn case<'a>(oracle: &'a Oracle, name: &str) -> &'a Case {
    oracle
        .cases
        .iter()
        .find(|c| c.name == name)
        .unwrap_or_else(|| panic!("oracle has no case {name:?}"))
}

pub(crate) fn assert_segments(name: &str, got: &[GlyphSegment], want: &[GlyphSegment]) {
    assert_eq!(got.len(), want.len(), "{name}: segment count");
    for (i, (g, w)) in got.iter().zip(want).enumerate() {
        assert!(
            g.point == w.point && g.handle_in == w.handle_in && g.handle_out == w.handle_out,
            "{name} segment {i}: got {g:?} want {w:?}"
        );
    }
}
